project_budget_details_paginated_query:
query BusinessPlanningBudgetDetailsPaginated($budgetId: ID!, $first: PositiveInt!, $after: String) {
  businessPlanningBudget(budgetId: $budgetId) {
    budgetId
    budgetName
    budgetType
    linkedEntityId
    total
    state
    syncToken
    budgetDetailsPaginated(first: $first, after: $after, sortBy: [{ field: SEQUENCE_ID, direction: ASC }]) {
      edges {
        node { sequenceId order type itemId unitCost quantity amount description date accountId klassId locationId }
        cursor
      }
      pageInfo { hasNextPage hasPreviousPage startCursor endCursor }
    }
  }
}

custom_field_definitions_query:
query GetCustomFieldDefinitions($cursor: String) {
  appFoundationsCustomFieldDefinitions(
    filters: { active: true }
    first: 50
    after: $cursor
  ) {
    edges {
      cursor
      node {
        id
        legacyID
        legacyIDV2
        label
        dataType
        required
        active
        colorCode
        entityVersion
        createdSource
        dropDownOptions { id value active order }
        associations {
          associatedEntity
          associationCondition
          active
          allowedOperations
          subAssociations { associatedSubEntity active }
          validationOptions { maxLength minLength }
        }
      }
    }
    pageInfo { hasNextPage hasPreviousPage startCursor endCursor }
  }
}

custom_field_create_definition_mutation:
mutation CreateCustomFieldDefinition($input: AppFoundations_CustomFieldDefinitionCreateInput!) {
  appFoundationsCreateCustomFieldDefinition(input: $input) {
    id
    legacyIDV2
    label
    dataType
    required
    active
    dropDownOptions { id value active order }
    associations {
      associatedEntity
      associationCondition
      active
      allowedOperations
    }
  }
}

custom_field_update_definition_mutation:
mutation UpdateCustomFieldDefinition($input: AppFoundations_CustomFieldDefinitionUpdateInput!) {
  appFoundationsUpdateCustomFieldDefinition(input: $input) {
    id
    legacyIDV2
    label
    dataType
    active
    required
  }
}
